#!/usr/bin/env python3
"""Deterministic local invariant check for the CVE-2020-0543 cpu_matches() port.

Runs inside a checkout of the target+patch (cwd == checkout root). Verifies that:
  * exactly one cpu_matches() definition exists and takes the table parameter;
  * the body looks up the caller-supplied table, not cpu_vuln_whitelist;
  * every cpu_matches() call passes cpu_vuln_whitelist as the first argument;
  * exactly the 8 pre-existing bug-bit call sites are present;
  * no old bare-bit call form remains.

Exit 0 on success, 1 on any violation.
"""
import re
import sys
from pathlib import Path

PATH = Path("arch/x86/kernel/cpu/common.c")
EXPECTED_BITS = [
    "NO_ITLB_MULTIHIT",
    "NO_SPECULATION",
    "NO_SSB",
    "NO_MDS",
    "MSBDS_ONLY",
    "NO_SWAPGS",
    "NO_MELTDOWN",
    "NO_L1TF",
]

errors = []
text = PATH.read_text(encoding="utf-8")
lines = text.splitlines()

definition_re = re.compile(
    r"^static bool __init cpu_matches\(const struct x86_cpu_id \*table, unsigned long which\)$"
)
defs = [i for i, l in enumerate(lines, 1) if definition_re.match(l)]
if len(defs) != 1:
    errors.append(f"expected exactly 1 parameterized cpu_matches definition, found {defs}")

# Body lookup must use the passed table.
body_ok = any(
    "x86_match_cpu(table)" in line for line in lines
)
bad_body = any(
    "x86_match_cpu(cpu_vuln_whitelist)" in line for line in lines
)
if not body_ok:
    errors.append("cpu_matches body does not call x86_match_cpu(table)")
if bad_body:
    errors.append("cpu_matches body still calls x86_match_cpu(cpu_vuln_whitelist)")

call_re = re.compile(r"cpu_matches\(([^)]*)\)")
calls = []
for i, l in enumerate(lines, 1):
    if definition_re.match(l):
        continue
    for m in call_re.finditer(l):
        calls.append((i, m.group(1).strip()))

if len(calls) != 8:
    errors.append(f"expected 8 cpu_matches() call sites, found {len(calls)}: {calls}")

found_bits = set()
for lineno, args in calls:
    if not args.startswith("cpu_vuln_whitelist,"):
        errors.append(f"line {lineno}: call does not pass cpu_vuln_whitelist first: cpu_matches({args})")
        continue
    rest = args.split(",", 1)[1].strip()
    found_bits.add(rest)

if found_bits != set(EXPECTED_BITS):
    errors.append(f"bug-bit call set mismatch: found {sorted(found_bits)} expected {sorted(EXPECTED_BITS)}")

# Target behavior preservation: Spectre V2 must remain unconditional (no NO_SPECTRE_V2 at target).
if "NO_SPECTRE_V2" in text:
    errors.append("unexpected NO_SPECTRE_V2 introduced; target branch has no such symbol")

if errors:
    print("CHECK FAILED")
    for e in errors:
        print(" -", e)
    sys.exit(1)

print("CHECK PASSED: 1 parameterized cpu_matches(), 8 cpu_vuln_whitelist call sites, Spectre V2 behavior unchanged")

