#!/usr/bin/env python3
"""Compile-and-run unit test for the patched cpu_matches() from a target checkout.

Runs with cwd == a checkout that already has generated.patch applied. It extracts
the real cpu_matches() definition text from arch/x86/kernel/cpu/common.c, stubs
the minimal x86_cpu_id / x86_match_cpu environment, and compiles with gcc-8.

Positive path (reference invariant): a table whose matched entry has the queried
bit set makes cpu_matches() return true.
Negative path (fix semantics): cpu_matches() must consult the *passed* table, so a
different table with the bit clear must make it return false, and an unmatched
table must return false (no implicit global whitelist fallback).

Exit 0 on success, 1 on any failure.
"""
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SRC = Path("arch/x86/kernel/cpu/common.c")
CC = os.environ.get("CC", "gcc-8")

text = SRC.read_text(encoding="utf-8")
m = re.search(
    r"^static bool __init cpu_matches\(const struct x86_cpu_id \*table, unsigned long which\)\n"
    r"\{.*?\n\}",
    text,
    re.S | re.M,
)
if not m:
    print("FAIL: could not extract parameterized cpu_matches() definition")
    sys.exit(1)
func = m.group(0)

test_c = r"""
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

#define __init

struct x86_cpu_id {
	unsigned short vendor;
	unsigned short family;
	unsigned short model;
	unsigned short steppings;
	unsigned short feature;
	unsigned long driver_data;
};

#define BIT(x) (1UL << (x))

/* Two distinct tables plus an unmatched one, selected by identity. */
static const struct x86_cpu_id table_a[] = {
	{ .vendor = 0x1, .driver_data = BIT(3) | BIT(5) },
	{}
};
static const struct x86_cpu_id table_b[] = {
	{ .vendor = 0x2, .driver_data = BIT(5) },
	{}
};

static const struct x86_cpu_id *x86_match_cpu(const struct x86_cpu_id *match)
{
	if (match == table_a)
		return &table_a[0];
	if (match == table_b)
		return &table_b[0];
	return 0;
}

/* ---- extracted from the patched target source ---- */
__FUNC__

int main(void)
{
	int failures = 0;

	/* positive path: bit 3 set in table_a */
	if (cpu_matches(table_a, BIT(3)) != true) {
		printf("FAIL: positive path table_a bit3 expected true\n");
		failures++;
	}
	/* negative path 1: bit 3 is NOT in table_b */
	if (cpu_matches(table_b, BIT(3)) != false) {
		printf("FAIL: negative path table_b bit3 expected false (wrong table used?)\n");
		failures++;
	}
	/* negative path 2: bit 5 is in both -> true under either table */
	if (cpu_matches(table_a, BIT(5)) != true || cpu_matches(table_b, BIT(5)) != true) {
		printf("FAIL: shared bit 5 expected true\n");
		failures++;
	}
	/* negative path 3: unmatched table yields false, no global fallback */
	struct x86_cpu_id other[1] = { { 0 } };
	if (cpu_matches(other, BIT(3)) != false) {
		printf("FAIL: unmatched table expected false\n");
		failures++;
	}
	if (failures) {
		printf("RUNTIME CHECK FAILED (%d)\n", failures);
		return 1;
	}
	printf("RUNTIME CHECK PASSED: table-scoped matching honored (positive + negative paths)\n");
	return 0;
}
""".replace("__FUNC__", func)

with tempfile.TemporaryDirectory(prefix="cpu-matches-test-") as tmp:
    cpath = Path(tmp) / "test_cpu_matches.c"
    binpath = Path(tmp) / "test_cpu_matches"
    cpath.write_text(test_c, encoding="utf-8")
    compile_res = subprocess.run(
        [CC, "-std=gnu99", "-Wall", "-Werror", "-O2", str(cpath), "-o", str(binpath)],
        capture_output=True, text=True,
    )
    if compile_res.returncode != 0:
        print("FAIL: compile error")
        print(compile_res.stderr)
        sys.exit(1)
    run_res = subprocess.run([str(binpath)], capture_output=True, text=True)
    sys.stdout.write(run_res.stdout)
    sys.stderr.write(run_res.stderr)
    sys.exit(run_res.returncode)

